import{_ as t,c as o,b as n,o as a}from"./app-CpW5lisY.js";const l={};function i(r,e){return a(),o("div",null,e[0]||(e[0]=[n('<p><a href="https://marketplace-doc.webkul.com/classic/Introduction/" target="_blank" rel="noopener noreferrer">Multivendor Marketplace app for Shopify</a>-Weglot Translation- We have now integrated the Weglot translation tool in our multivendor marketplace app</p><p>Through which multivendor apps can now be translated into multiple languages as per the weglot translation plans.</p><h3 id="features" tabindex="-1"><a class="header-anchor" href="#features"><span>FEATURES</span></a></h3><ul><li>Admin can convert his/her multivendor marketplace app to multiple languages.</li><li>Admin can give the options to their sellers to select the language of their choice.</li><li>Also, admin can even choose whether he/she wants to avail the options of multiple languages to only admin, to the only seller or to both.</li><li>This app is free but you need to subscribe to any of &quot;Weglot&quot; Plans. To check Weglot Pricing  <a href="https://weglot.com/pricing" target="_blank" rel="noopener noreferrer">click here</a></li></ul><p>So let&#39;s understand its workflow:</p><h3 id="workflow-in-new-theme" tabindex="-1"><a class="header-anchor" href="#workflow-in-new-theme"><span>WORKFLOW in New Theme</span></a></h3><p>Firstly you need to Enable &quot;Weglot Translation&quot; from the &#39;Feature Apps&#39; section by clicking on the (...) three dots on the top right-hand side of the main menu.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/29112705/AwesomeScreenshot-Feature-Apps-Admin-2019-07-29-16-07-76.png" alt="Weglot Translation"></p><p>After enabling the &quot; Weglot Translation&quot; you need to click on the agree button.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/b-1.png" alt="Weglot Translation"></p><p>Once you will click on &quot;Agree Button&quot; you will be redirected to the &quot;Weglot&quot; Sign Up page and there you need to register on Weglot and need to get an API key to have your app in multiple languages.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/07/image-14-1200x597.png" alt="image-14"></p><p>After signup to &quot;Weglot&quot;, you will get an email for verification. Further, follow these steps: <a href="https://weglot.com/documentation/setup-guides/generic-setup-guide/" target="_blank" rel="noopener noreferrer">https://weglot.com/documentation/setup-guides/generic-setup-guide/</a></p><p>Once done, you&#39;ll have the API key that will be used in the Multivendor Weglot Configuration.</p><h3 id="admin-end" tabindex="-1"><a class="header-anchor" href="#admin-end"><span>ADMIN END</span></a></h3><p>Now you will get a menu name &quot;Weglot configuration&quot; in the configuration section of your multivendor marketplace app.</p><p>Here you need to Enter the &quot;API&quot; key.</p><p>You also need to keep the default language is English.</p><p>Go to the Admin Panel&gt;&gt;Click the <strong>Configuration</strong> menu&gt;&gt;<strong>Scroll down</strong> and click the <strong>Weglot Configuration</strong>&gt;&gt; Enter &quot;API KEY&quot; &gt;&gt;fill the rest details&gt;&gt; Save.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/06/Screenshot-2020-06-08T161100.890-1200x600.png" alt="weglot"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/e-1.png" alt="Weglot Translation"></p><p>Hence, a menu with the selected languages will be visible on the bottom corner in the right-hand side as shown in the below screenshot.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/h-3.png" alt="Weglot Translation"></p><p>So now just change the language of your Multivendor Marketplace app at your convenience.</p><h3 id="demo" tabindex="-1"><a class="header-anchor" href="#demo"><span>DEMO</span></a></h3><p>Check out: <a href="https://multivendor-marketplace-5.myshopify.com/" target="_blank" rel="noopener noreferrer">https://multivendor-marketplace-5.myshopify.com/</a></p>',26)]))}const p=t(l,[["render",i]]),c=JSON.parse('{"path":"/classic/Featured-App/Marketplace%20Miscellaneous%20Add-ons/WEGLOT%20TRANSLATION.html","title":"Weglot Translation","lang":"en-US","frontmatter":{"title":"Weglot Translation","description":"Weglot Translation","date":"2025-07-25T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[{"level":3,"title":"FEATURES","slug":"features","link":"#features","children":[]},{"level":3,"title":"WORKFLOW in New Theme","slug":"workflow-in-new-theme","link":"#workflow-in-new-theme","children":[]},{"level":3,"title":"ADMIN END","slug":"admin-end","link":"#admin-end","children":[]},{"level":3,"title":"DEMO","slug":"demo","link":"#demo","children":[]}],"git":{"updatedTime":1757583088000,"contributors":[{"name":"pratik","username":"pratik","email":"pratik@webkul.com","commits":1,"url":"https://github.com/pratik"}],"changelog":[{"hash":"bbe1b03e5e919255cadeb8590203b7f1b2e7378e","time":1757583088000,"email":"pratik@webkul.com","author":"pratik","message":"add some new file"}]},"filePathRelative":"classic/Featured-App/Marketplace Miscellaneous Add-ons/WEGLOT TRANSLATION.md"}');export{p as comp,c as data};
